enum class resume_kind : std::uint8_t { publication, completion };
/* Bounded bookkeeping for the selected all-stop-on-non-stop completion.
   This carries no native owner/authority and has no reset or recovery path. */
enum class completion_edge : std::uint8_t {
  cpu_begin, cpu_return, cpu_body, cpu_generic,
  wave_begin, wave_return, wave_body, wave_generic,
  commit_begin, commit_amd, commit_generic, count
};
class completion_sequence final {
public:
  bool expects (completion_edge edge) const noexcept {
    return !m_failed && m_next == static_cast<unsigned> (edge);
  }
  bool advance (completion_edge edge) noexcept {
    if (edge == completion_edge::count || !expects (edge)) {
      m_failed = true; return false;
    }
    ++m_next; return true;
  }
  bool completed () const noexcept { return expects (completion_edge::count); }
private:
  std::uint8_t m_next = 0;
  bool m_failed = false;
};
static_assert (sizeof (completion_sequence) == 2, "fixed completion sequence");
